      moat:["五粮液具备全国品牌心智、浓香工艺与稀缺优质基酒资源。","第八代普五在千元价格带拥有广泛渠道和宴席基础，但批价稳定性与茅台存在差距。","轻资产、高毛利和现金储备提供周期生存力，渠道库存和国企激励则影响护城河兑现。"],
      masterViews:[{name:"巴菲特视角",verdict:"品牌仍强，所有者收益需正常化",text:"高毛利、轻资本和全国品牌具经济商誉，但当前TTM利润失真，经营现金流又未确认修复。69.85元是否便宜应依据去库存后的可分配现金，而不是历史高峰利润或表面PE。"},{name:"芒格视角",verdict:"低价、高分红和名酒叙事需反证",text:"最容易出现的偏误是把历史品牌、低股价和政策承诺组合成确定性。应反向观察经销商激励、批价、合同负债和开瓶；若报表增长不能转为回款，可能是时点而非生意改善。"},{name:"段永平视角",verdict:"用户价值可理解，渠道逻辑尚未讲清",text:"消费者为何选择五粮液能够解释，商业模式也具有高现金潜力；但当前渠道价格、库存与公司确认收入之间仍有噪音。只有真实消费和自由现金流恢复后，当前价格的吸引力才可靠。"},{name:"散户乙视角",verdict:"不会轻易消失，但十年分红回本仍慢",text:"品牌、现金和低负债使公司在最坏白酒周期中仍能生存，符合不加杠杆等待的前提。当前可持续股息率约4%，不足以十年靠分红回本；需要更低成本或更明确的利润底。"},{name:"韦尔奇视角",verdict:"控货去库要用一线结果验收",text:"数字化营销、开瓶扫码和渠道调整方向明确，关键是组织是否允许真实批价和库存向上传递。应以经销商利润、终端周转、重点区域份额和低效产品收缩评价新团队，而非累计收入目标。"}],
