    masterViews:[{name:"巴菲特视角",verdict:"看扣除租赁支出后的所有者收益",text:"品牌和渠道有价值，H1自由现金流却明显低于经营现金流。净债务与收购付款占用现金，现价基准10.7%税前回报仍低于12%要求，不能仅凭8倍历史PE认定便宜。"},{name:"芒格视角",verdict:"反向检验需求、费用和杠杆同时恶化",text:"旅游需求下降、广告获客变贵与租金刚性可能叠加；如果再以借款支持并购和分红，低估值的缓冲会被消耗。不要把美国上市当作必然重估。"},{name:"段永平视角",verdict:"产品与品牌可理解，持续提价能力待验证",text:"消费者愿为轮组、耐用和售后付费，是比品牌历史更具体的价值。要看TUMI和Samsonite能否在减少折扣时保持销量，营销投入是否形成长期客户偏好。"},{name:"散户乙视角",verdict:"高历史股息需扣税并防利润下修",text:"税前约6.5%与公告税后约5.6%不是同一个现金回报。股息已派，买入后的未来分红仍受盈利和债务约束；下行情景十年回报仅约0.7%，需要能承受消费周期。"},{name:"韦尔奇视角",verdict:"按品牌与渠道考核现金回报",text:"资源应投向能改善销量、库存周转和租赁后现金流的品牌渠道。BÉIS整合需保留品牌团队优势，同时用新增资本回报评估协同，避免只追求销售规模。"}],
