    const declared = HKD_MODEL_FX[stock.code];
    if (!declared) throw new Error(`港股模型缺少币种声明：${stock.code} ${stock.name}`);
    stock.model.fx = Object.assign({}, declared, { rateSource: FX_RATE_SOURCE[declared.reportCurrency] });
