    references:[{label:"宁德时代2026半年报",date:"2026-07-25",url:catl.sources[0][2],locator:"印刷页7（归母/扣非）、15—17（产品毛利/产能）、合并现金流表和股本附注",status:"已核原文；资本现金支出与股数由妙想交叉核对"},{label:"2025年报",date:"2026-03-10",url:catl.sources[1][2],locator:"主要会计数据和合并现金流表",status:"原文指标与妙想对照；未来分配并非公司承诺"}]
